/**
 * ★ このメソッドを "CallCanvas: Open Viewer with File" で解析すると、
 *   IService#execute(String, String[], ...) の先が解析されない（不具合）
 *
 * 原因: config.getString() の型 (org.apache.commons.configuration.Configuration) が
 *       tool の --classes に未登録のため facade.solve() が失敗し、
 *       フォールバックが引数の数のみで誤ったオーバーロードを選択する。
 *
 * @param to        送信先アドレス
 * @param customArgs カスタムパラメーター
 * @return 処理結果
 */
public boolean doProcess(String to, Map<String, String> customArgs) {
    // ★ ここで IService#execute(String, String[], ...) を呼び出す
    // config.getString() の戻り型が facade で解決できないため
    // call-index.json には execute(String[], String[], ...) と誤って記録される
    boolean result = service.execute(
            to,
            null,
            customArgs.get("title"),
            customArgs.get("body"),
            config.getString("name"),   // ← Configuration は --classes 外 → facade 失敗の原因
            "SystemName",
            null,
            customArgs,
            config.getString("key")         // ← 同上
    );

    return result;
}

@Override
public boolean execute(String p1, String[] p2, String p3, String p4, String p5, String p6, String p7,
                       Map<String, String> p8, String p9) {
    return execute(new String[]{p1}, p2, p3, p4, p5, p6, p7, p8, p9);
}

@Override
public boolean execute(String[] p1, String[] p2, String p3, String p4, String p5, String p6, String p7,
